import React, { useState, useEffect, useContext } from 'react';
import { Link } from 'react-router-dom';
import { Building2, Plus, Search, Filter, Edit2, CheckCircle2, ShieldAlert, MoreVertical, Briefcase, Mail, Phone, Globe, X, ExternalLink, ChevronRight, Users, TrendingUp, Clock } from 'lucide-react';
import { AppContext } from '../../App';
import { EmployerService } from '../../domain/employerService';

const EmployerManagement = () => {
  const { userType } = useContext(AppContext);
  const [employers, setEmployers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [selectedEmployer, setSelectedEmployer] = useState(null);
  const [isEditing, setIsEditing] = useState(false);
  const [formData, setFormData] = useState({
    companyName: '',
    email: '',
    phone: '',
    website: '',
    address: '',
    industry: '',
    companySize: '',
    description: '',
    contactPerson: '',
    contactDesignation: ''
  });
  const [message, setMessage] = useState('');
  const [formLoading, setFormLoading] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  useEffect(() => {
    loadEmployers();
  }, []);

  const loadEmployers = async () => {
    try {
      setLoading(true);
      const employersData = await EmployerService.getAllEmployers();
      setEmployers(employersData);
    } catch (error) {
      console.error('Failed to load employers:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleAddEmployer = () => {
    setSelectedEmployer(null);
    setIsEditing(false);
    setFormData({
      companyName: '',
      email: '',
      phone: '',
      website: '',
      address: '',
      industry: '',
      companySize: '',
      description: '',
      contactPerson: '',
      contactDesignation: ''
    });
    setMessage('');
    setShowModal(true);
  };

  const handleEditEmployer = (employer) => {
    setSelectedEmployer(employer);
    setIsEditing(true);
    setFormData({
      companyName: employer.companyName,
      email: employer.email,
      phone: employer.phone,
      website: employer.website,
      address: employer.address,
      industry: employer.industry,
      companySize: employer.companySize,
      description: employer.description,
      contactPerson: employer.contactPerson,
      contactDesignation: employer.contactDesignation
    });
    setMessage('');
    setShowModal(true);
  };

  const handleVerifyEmployer = async (employerId) => {
    try {
      await EmployerService.verifyEmployer(employerId);
      setMessage('Employer verified successfully!');
      loadEmployers();
    } catch (error) {
      setMessage(error.message);
    }
  };

  const handleInputChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setFormLoading(true);
    setMessage('');

    try {
      if (isEditing) {
        await EmployerService.updateEmployerProfile(selectedEmployer.id, formData);
        setMessage('Employer profile updated successfully!');
      } else {
        await EmployerService.registerEmployer(formData);
        setMessage('New employer registered successfully!');
      }

      setTimeout(() => {
        setShowModal(false);
        loadEmployers();
      }, 2000);
    } catch (error) {
      setMessage(error.message);
    } finally {
      setFormLoading(false);
    }
  };

  const getVerificationBadge = (isVerified) => {
    return isVerified ? (
      <span className="bg-emerald-500/10 text-emerald-400 border border-emerald-500/20 px-3 py-1 rounded-full text-[10px] font-bold uppercase tracking-widest flex items-center gap-2">
        <CheckCircle2 size={12} /> Verified
      </span>
    ) : (
      <span className="bg-gold-500/10 text-gold-500 border border-gold-500/20 px-3 py-1 rounded-full text-[10px] font-bold uppercase tracking-widest flex items-center gap-2">
        <Clock size={12} /> Pending
      </span>
    );
  };

  const filteredEmployers = employers.filter(emp => 
    emp.companyName.toLowerCase().includes(searchTerm.toLowerCase()) ||
    emp.industry.toLowerCase().includes(searchTerm.toLowerCase())
  );

  if (loading) {
    return (
      <div className="min-h-screen bg-onyx-900 flex items-center justify-center">
        <div className="w-12 h-12 border-4 border-gold-500/20 border-t-gold-500 rounded-full animate-spin"></div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-onyx-900 pb-24 font-sans text-pearl-200">
      {/* Cinematic Header Area */}
      <div className="h-64 bg-onyx-950 relative overflow-hidden">
        <div className="absolute inset-0 bg-gold-gradient opacity-[0.03]"></div>
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[1000px] h-[1000px] bg-gold-500/5 rounded-full blur-[150px]"></div>

        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-full flex flex-col justify-center relative z-10">
          <div className="flex flex-col md:flex-row md:items-end justify-between gap-8">
            <div>
              <h1 className="text-4xl md:text-6xl font-serif font-bold text-white tracking-tight leading-none mb-4">Employer Registry</h1>
              <p className="text-pearl-500 text-lg font-light tracking-wide italic">Managing the global corporate elite.</p>
            </div>
            {userType === 'admin' && (
              <button 
                onClick={handleAddEmployer}
                className="bg-gold-gradient text-onyx-900 px-8 py-4 rounded-2xl font-black uppercase tracking-[0.2em] text-xs hover:brightness-110 transition-all shadow-gold flex items-center gap-3 w-fit"
              >
                <Plus size={18} /> Register Institution
              </button>
            )}
          </div>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 -mt-12 relative z-20">

        {/* Statistics Bar */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-12">
          <div className="glass rounded-3xl p-8 border border-pearl-900/10 shadow-xl group hover:border-gold-500/30 transition-all">
            <div className="flex justify-between items-start mb-4">
              <div className="w-12 h-12 rounded-2xl bg-white/5 flex items-center justify-center text-pearl-500 group-hover:text-gold-500 transition-colors">
                <Building2 size={24} />
              </div>
              <TrendingUp size={16} className="text-emerald-500" />
            </div>
            <p className="text-[10px] font-black text-pearl-700 uppercase tracking-[0.2em] mb-1">Total Registry</p>
            <h3 className="text-4xl font-serif font-bold text-white leading-none">{employers.length}</h3>
          </div>

          <div className="glass rounded-3xl p-8 border border-pearl-900/10 shadow-xl group hover:border-gold-500/30 transition-all">
            <div className="flex justify-between items-start mb-4">
              <div className="w-12 h-12 rounded-2xl bg-white/5 flex items-center justify-center text-pearl-500 group-hover:text-gold-500 transition-colors">
                <CheckCircle2 size={24} />
              </div>
              <ShieldAlert size={16} className="text-emerald-500" />
            </div>
            <p className="text-[10px] font-black text-pearl-700 uppercase tracking-[0.2em] mb-1">Authenticated</p>
            <h3 className="text-4xl font-serif font-bold text-white leading-none">{employers.filter(e => e.isVerified).length}</h3>
          </div>

          <div className="glass rounded-3xl p-8 border border-pearl-900/10 shadow-xl group hover:border-gold-500/30 transition-all">
            <div className="flex justify-between items-start mb-4">
              <div className="w-12 h-12 rounded-2xl bg-white/5 flex items-center justify-center text-pearl-500 group-hover:text-gold-500 transition-colors">
                <Clock size={24} />
              </div>
              <span className="text-[10px] font-bold text-gold-500 uppercase tracking-widest">Active</span>
            </div>
            <p className="text-[10px] font-black text-pearl-700 uppercase tracking-[0.2em] mb-1">Awaiting Review</p>
            <h3 className="text-4xl font-serif font-bold text-white leading-none">{employers.filter(e => !e.isVerified).length}</h3>
          </div>

          <div className="glass rounded-3xl p-8 border border-pearl-900/10 shadow-xl group hover:border-gold-500/30 transition-all">
            <div className="flex justify-between items-start mb-4">
              <div className="w-12 h-12 rounded-2xl bg-white/5 flex items-center justify-center text-pearl-500 group-hover:text-gold-500 transition-colors">
                <Briefcase size={24} />
              </div>
              <TrendingUp size={16} className="text-emerald-500" />
            </div>
            <p className="text-[10px] font-black text-pearl-700 uppercase tracking-[0.2em] mb-1">Global Opportunities</p>
            <h3 className="text-4xl font-serif font-bold text-white leading-none">
              {employers.reduce((total, emp) => total + (emp.jobsPosted ? emp.jobsPosted.length : 0), 0)}
            </h3>
          </div>
        </div>

        {/* Search & Filter Bar */}
        <div className="glass rounded-[2.5rem] border border-pearl-900/10 p-4 mb-10 flex flex-col md:flex-row gap-4 items-center shadow-2xl">
          <div className="relative flex-1 w-full">
            <Search className="absolute left-6 top-1/2 -translate-y-1/2 text-pearl-700" size={20} />
            <input 
              type="text" 
              placeholder="Filter by institution or industry vertical..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full bg-onyx-800/50 border border-pearl-900/10 rounded-2xl py-4 pl-16 pr-6 text-white outline-none focus:border-gold-500/50 transition-all font-light"
            />
          </div>
          <button className="glass px-8 py-4 rounded-2xl border border-pearl-900/10 text-pearl-400 font-bold flex items-center gap-3 hover:bg-white/5 transition-all">
            <Filter size={20} /> Parameters
          </button>
        </div>

        {message && (
          <div className={`p-6 rounded-[2rem] mb-10 font-bold text-sm uppercase tracking-widest flex items-center gap-4 animate-fade-in-up ${message.includes('successfully') ? 'bg-emerald-500/10 text-emerald-400 border border-emerald-500/20' : 'bg-rose-500/10 text-rose-400 border border-rose-500/20'}`}>
            <CheckCircle2 size={24} />
            {message}
          </div>
        )}

        {/* Registry Table */}
        <div className="glass rounded-[3rem] border border-pearl-900/10 overflow-hidden shadow-2xl">
          <div className="px-10 py-8 border-b border-pearl-900/10 flex justify-between items-center bg-white/5">
            <h3 className="text-2xl font-serif font-bold text-white">Elite Institutions</h3>
            <span className="text-[10px] font-black text-pearl-700 uppercase tracking-[0.3em] italic">Full Catalog</span>
          </div>

          <div className="overflow-x-auto">
            <table className="w-full text-left border-collapse">
              <thead>
                <tr className="bg-onyx-950/50 text-pearl-700 text-[10px] uppercase tracking-[0.2em] font-black">
                  <th className="py-8 px-10">Corporate Entity</th>
                  <th className="py-8 px-10">Vertical</th>
                  <th className="py-8 px-10">Primary Envoy</th>
                  <th className="py-8 px-10">Status</th>
                  <th className="py-8 px-10">Intel</th>
                  <th className="py-8 px-10 text-right">Operations</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-pearl-900/5">
                {filteredEmployers.map(employer => (
                  <tr key={employer.id} className="hover:bg-white/[0.02] transition-colors group">
                    <td className="py-8 px-10">
                      <Link to={`/employer/${employer.id}`} className="flex items-center gap-5 group/link">
                        <div className="w-14 h-14 rounded-2xl bg-onyx-800 p-2 border border-pearl-900/10 overflow-hidden shrink-0 group-hover/link:border-gold-500/30 transition-all">
                          <img src={employer.logo || 'https://via.placeholder.com/100'} alt="Logo" className="w-full h-full object-contain grayscale group-hover/link:grayscale-0 transition-all duration-500" />
                        </div>
                        <div>
                          <p className="font-serif font-bold text-white text-xl tracking-tight leading-tight group-hover/link:text-gold-400 transition-colors">{employer.companyName}</p>
                          <p className="text-pearl-600 text-xs font-light tracking-wide flex items-center gap-2">
                             <ExternalLink size={10} /> {employer.website?.replace(/^https?:\/\//, '')}
                          </p>
                        </div>
                      </Link>
                    </td>
                    <td className="py-8 px-10">
                      <span className="text-pearl-400 font-light text-sm uppercase tracking-widest">{employer.industry}</span>
                    </td>
                    <td className="py-8 px-10">
                      <div>
                        <p className="text-pearl-200 font-bold text-sm leading-tight">{employer.contactPerson}</p>
                        <p className="text-pearl-700 text-[10px] font-black uppercase tracking-widest mt-1">{employer.contactDesignation}</p>
                      </div>
                    </td>
                    <td className="py-8 px-10">
                      {getVerificationBadge(employer.isVerified)}
                    </td>
                    <td className="py-8 px-10">
                      <span className="flex items-center gap-2 text-pearl-400 font-bold text-sm">
                        <Briefcase size={16} className="text-gold-500/30" /> {employer.jobsPosted ? employer.jobsPosted.length : 0}
                      </span>
                    </td>
                    <td className="py-8 px-10 text-right">
                      <div className="flex gap-3 justify-end opacity-0 group-hover:opacity-100 transition-opacity">
                        <Link 
                          to={`/employer/${employer.id}`}
                          className="w-10 h-10 rounded-xl glass border border-pearl-900/10 flex items-center justify-center text-pearl-600 hover:text-white hover:border-pearl-200 transition-all"
                        >
                          <ChevronRight size={18} />
                        </Link>
                        {userType === 'admin' && (
                          <>
                            <button 
                              onClick={() => handleEditEmployer(employer)}
                              className="w-10 h-10 rounded-xl glass border border-pearl-900/10 flex items-center justify-center text-pearl-600 hover:text-gold-500 hover:border-gold-500/30 transition-all"
                            >
                              <Edit2 size={18} />
                            </button>
                            {!employer.isVerified && (
                              <button 
                                onClick={() => handleVerifyEmployer(employer.id)}
                                className="w-10 h-10 rounded-xl glass border border-pearl-900/10 flex items-center justify-center text-emerald-600 hover:text-emerald-400 hover:border-emerald-500/30 transition-all"
                              >
                                <CheckCircle2 size={18} />
                              </button>
                            )}
                          </>
                        )}
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          {filteredEmployers.length === 0 && (
            <div className="p-24 text-center">
              <div className="w-24 h-24 bg-onyx-800 rounded-3xl flex items-center justify-center mx-auto mb-8 border border-pearl-900/10">
                <Search className="text-pearl-800" size={40} />
              </div>
              <h4 className="text-2xl font-serif font-bold text-white mb-2">No matching institutions</h4>
              <p className="text-pearl-600 font-light italic">Refine your parameters and try again.</p>
            </div>
          )}
        </div>
      </div>

      {/* Add/Edit Institution Modal */}
      {showModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 sm:p-6 bg-onyx-950/80 backdrop-blur-md overflow-y-auto">
          <div className="glass rounded-[3rem] w-full max-w-4xl shadow-[0_0_50px_rgba(0,0,0,0.5)] border border-pearl-900/10 overflow-hidden my-auto animate-fade-in-up">
            <div className="px-10 py-8 border-b border-pearl-900/10 flex justify-between items-center bg-white/5">
              <h3 className="text-2xl font-serif font-bold text-white">
                {isEditing ? 'Refine Institution Profile' : 'Catalog New Institution'}
              </h3>
              <button onClick={() => setShowModal(false)} className="text-pearl-600 hover:text-white bg-onyx-800 p-2.5 rounded-xl transition-all border border-pearl-900/10">
                <X size={20} />
              </button>
            </div>

            <div className="p-10 max-h-[75vh] overflow-y-auto custom-scrollbar">
              {message && (
                <div className={`p-5 rounded-2xl mb-8 font-bold text-sm uppercase tracking-widest flex items-start gap-4 ${message.includes('successfully') ? 'bg-emerald-500/10 text-emerald-400 border border-emerald-500/20' : 'bg-rose-500/10 text-rose-400 border border-rose-500/20'}`}>
                  {message.includes('successfully') ? <CheckCircle2 size={20} className="shrink-0" /> : <X size={20} className="shrink-0" />}
                  <p>{message}</p>
                </div>
              )}

              <form onSubmit={handleSubmit} className="space-y-12">

                {/* Identity Section */}
                <div>
                  <h4 className="text-[10px] font-black text-gold-500 uppercase tracking-[0.3em] mb-8 flex items-center gap-3">
                    <span className="w-8 h-px bg-gold-500/30"></span>
                    Identity & Vertical
                  </h4>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                    <div>
                      <label className="block text-[10px] font-black text-pearl-700 uppercase tracking-[0.2em] mb-3">Institution Name</label>
                      <input type="text" name="companyName" value={formData.companyName} onChange={handleInputChange} required className="w-full px-5 py-4 rounded-2xl bg-onyx-800 border border-pearl-900/10 focus:border-gold-500 outline-none transition-all font-medium text-white" />
                    </div>
                    <div>
                      <label className="block text-[10px] font-black text-pearl-700 uppercase tracking-[0.2em] mb-3">Industry Vertical</label>
                      <select name="industry" value={formData.industry} onChange={handleInputChange} required className="w-full px-5 py-4 rounded-2xl bg-onyx-800 border border-pearl-900/10 focus:border-gold-500 outline-none transition-all font-medium text-white appearance-none cursor-pointer">
                        <option value="">Select Vertical</option>
                        <option value="Software Development">Software Development</option>
                        <option value="Data Analytics">Data Analytics</option>
                        <option value="Technology Consulting">Technology Consulting</option>
                        <option value="Financial Services">Financial Services</option>
                        <option value="Healthcare">Healthcare</option>
                        <option value="Manufacturing">Manufacturing</option>
                        <option value="Education">Education</option>
                        <option value="Other">Other</option>
                      </select>
                    </div>
                  </div>
                </div>

                {/* Connectivity Section */}
                <div>
                  <h4 className="text-[10px] font-black text-gold-500 uppercase tracking-[0.3em] mb-8 flex items-center gap-3">
                    <span className="w-8 h-px bg-gold-500/30"></span>
                    Digital Connectivity
                  </h4>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-8">
                    <div>
                      <label className="block text-[10px] font-black text-pearl-700 uppercase tracking-[0.2em] mb-3">Corporate Email</label>
                      <div className="relative group">
                        <Mail className="absolute left-5 top-1/2 -translate-y-1/2 text-pearl-800 group-focus-within:text-gold-500 transition-colors" size={18} />
                        <input type="email" name="email" value={formData.email} onChange={handleInputChange} required className="w-full px-5 py-4 pl-14 rounded-2xl bg-onyx-800 border border-pearl-900/10 focus:border-gold-500 outline-none transition-all font-medium text-white" />
                      </div>
                    </div>
                    <div>
                      <label className="block text-[10px] font-black text-pearl-700 uppercase tracking-[0.2em] mb-3">Phone Line</label>
                      <div className="relative group">
                        <Phone className="absolute left-5 top-1/2 -translate-y-1/2 text-pearl-800 group-focus-within:text-gold-500 transition-colors" size={18} />
                        <input type="tel" name="phone" value={formData.phone} onChange={handleInputChange} required className="w-full px-5 py-4 pl-14 rounded-2xl bg-onyx-800 border border-pearl-900/10 focus:border-gold-500 outline-none transition-all font-medium text-white" />
                      </div>
                    </div>
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                    <div>
                      <label className="block text-[10px] font-black text-pearl-700 uppercase tracking-[0.2em] mb-3">Global Domain</label>
                      <div className="relative group">
                        <Globe className="absolute left-5 top-1/2 -translate-y-1/2 text-pearl-800 group-focus-within:text-gold-500 transition-colors" size={18} />
                        <input type="url" name="website" value={formData.website} onChange={handleInputChange} required placeholder="https://www.company.com" className="w-full px-5 py-4 pl-14 rounded-2xl bg-onyx-800 border border-pearl-900/10 focus:border-gold-500 outline-none transition-all font-medium text-white" />
                      </div>
                    </div>
                    <div>
                      <label className="block text-[10px] font-black text-pearl-700 uppercase tracking-[0.2em] mb-3">Institution Scale</label>
                      <select name="companySize" value={formData.companySize} onChange={handleInputChange} className="w-full px-5 py-4 rounded-2xl bg-onyx-800 border border-pearl-900/10 focus:border-gold-500 outline-none transition-all font-medium text-white appearance-none cursor-pointer">
                        <option value="">Select Scale</option>
                        <option value="1-10">1-10 specialists</option>
                        <option value="11-50">11-50 specialists</option>
                        <option value="51-100">51-100 specialists</option>
                        <option value="101-500">101-500 specialists</option>
                        <option value="501-1000">501-1000 specialists</option>
                        <option value="1000+">Global Enterprise (1000+)</option>
                      </select>
                    </div>
                  </div>
                </div>

                {/* Operations Section */}
                <div>
                  <h4 className="text-[10px] font-black text-gold-500 uppercase tracking-[0.3em] mb-8 flex items-center gap-3">
                    <span className="w-8 h-px bg-gold-500/30"></span>
                    Operations & Envoy
                  </h4>
                  <div className="mb-8">
                    <label className="block text-[10px] font-black text-pearl-700 uppercase tracking-[0.2em] mb-3">Headquarters Address</label>
                    <div className="relative group">
                      <MapPin className="absolute left-5 top-1/2 -translate-y-1/2 text-pearl-800 group-focus-within:text-gold-500 transition-colors" size={18} />
                      <input type="text" name="address" value={formData.address} onChange={handleInputChange} required className="w-full px-5 py-4 pl-14 rounded-2xl bg-onyx-800 border border-pearl-900/10 focus:border-gold-500 outline-none transition-all font-medium text-white" />
                    </div>
                  </div>

                  <div className="mb-8">
                    <label className="block text-[10px] font-black text-pearl-700 uppercase tracking-[0.2em] mb-3">Institution Brief</label>
                    <textarea rows={4} name="description" value={formData.description} onChange={handleInputChange} placeholder="Summarize the institution's elite status and mission..." className="w-full px-5 py-4 rounded-2xl bg-onyx-800 border border-pearl-900/10 focus:border-gold-500 outline-none transition-all font-light text-pearl-300 resize-none leading-relaxed" />
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                    <div>
                      <label className="block text-[10px] font-black text-pearl-700 uppercase tracking-[0.2em] mb-3">Primary Envoy Name</label>
                      <div className="relative group">
                        <Users className="absolute left-5 top-1/2 -translate-y-1/2 text-pearl-800 group-focus-within:text-gold-500 transition-colors" size={18} />
                        <input type="text" name="contactPerson" value={formData.contactPerson} onChange={handleInputChange} required className="w-full px-5 py-4 pl-14 rounded-2xl bg-onyx-800 border border-pearl-900/10 focus:border-gold-500 outline-none transition-all font-medium text-white" />
                      </div>
                    </div>
                    <div>
                      <label className="block text-[10px] font-black text-pearl-700 uppercase tracking-[0.2em] mb-3">Envoy Designation</label>
                      <input type="text" name="contactDesignation" value={formData.contactDesignation} onChange={handleInputChange} placeholder="e.g., Talent Acquisition Lead" className="w-full px-5 py-4 rounded-2xl bg-onyx-800 border border-pearl-900/10 focus:border-gold-500 outline-none transition-all font-medium text-white" />
                    </div>
                  </div>
                </div>

                <div className="pt-10 flex gap-5 justify-end">
                  <button type="button" onClick={() => setShowModal(false)} disabled={formLoading} className="px-8 py-3.5 rounded-2xl font-bold text-pearl-500 glass hover:text-white transition-all">
                    Dismiss
                  </button>
                  <button type="submit" disabled={formLoading} className="px-8 py-3.5 rounded-2xl font-bold text-onyx-900 bg-gold-gradient hover:brightness-110 transition-all shadow-gold flex items-center gap-3">
                    {formLoading ? (
                      <><div className="w-4 h-4 border-2 border-onyx-900/30 border-t-onyx-900 rounded-full animate-spin"></div> Processing...</>
                    ) : (isEditing ? 'Sync Changes' : 'Execute Cataloging')}
                  </button>
                </div>
              </form>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

// Helper component for Building icon
const MapPin = ({ size, className }) => (
  <svg 
    width={size} 
    height={size} 
    viewBox="0 0 24 24" 
    fill="none" 
    stroke="currentColor" 
    strokeWidth="2" 
    strokeLinecap="round" 
    strokeLinejoin="round" 
    className={className}
  >
    <path d="M20 10c0 6-8 12-8 12s-8-6-8-12a8 8 0 0 1 16 0Z" />
    <circle cx="12" cy="10" r="3" />
  </svg>
);

export default EmployerManagement;
